import * as THREE from 'three';

// Generated by tools/native_mips.py using the original integer RGBA filter.
// Explicit levels preserve transparent RGB and avoid driver mip rounding.
export function nativeMipTexture(buffer) {
  const header = new DataView(buffer);
  if (buffer.byteLength < 20 || header.getUint32(0, true) !== 0x50494d4d || header.getUint32(4, true) !== 1) {
    throw new Error('Invalid Medium mip-chain header');
  }
  const width = header.getUint32(8, true), height = header.getUint32(12, true);
  const count = header.getUint32(16, true);
  if (!width || width !== height || (width & (width - 1)) || count !== Math.log2(width) + 1) {
    throw new Error('Invalid Medium mip-chain dimensions');
  }
  let offset = 20;
  const levels = [];
  for (let level = 0, size = width; level < count; level++, size /= 2) {
    const length = size * size * 4;
    if (offset + length > buffer.byteLength) throw new Error('Truncated Medium mip chain');
    levels.push({ data: new Uint8Array(buffer, offset, length), width: size, height: size });
    offset += length;
  }
  if (offset !== buffer.byteLength) throw new Error('Unexpected Medium mip-chain bytes');
  const texture = new THREE.DataTexture(levels[0].data, width, height, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.mipmaps = levels;
  texture.generateMipmaps = false;
  texture.flipY = false;
  texture.premultiplyAlpha = false;
  texture.colorSpace = THREE.NoColorSpace;
  texture.minFilter = THREE.LinearMipmapNearestFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.userData.nativeMipmaps = true;
  texture.needsUpdate = true;
  return texture;
}

export async function loadNativeMipTexture(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`Cannot load native mip chain: ${url} (${response.status})`);
  return nativeMipTexture(await response.arrayBuffer());
}
